mapper.select:
select * from (select aaa.* from (
UNION ALL
) aaa left join SYS_DATADICT_LIST sdl on aaa.finprodType2=sdl.ITEM_CODE and sdl.DICT_CODE='FINPROD_TYPE_TG' left join SYS_DATADICT_LIST dictps on aaa.PS=dictps.ITEM_CODE and dictps.DICT_CODE='PS' left join SYS_DATADICT_LIST dicttradeMarket on aaa.tradeMarket=dicttradeMarket.ITEM_CODE and dicttradeMarket.DICT_CODE='TRADE_PLACE'
order by aaa.finprodType2, aaa.ps DESC)
order by ${sort} ${direction}

mapper.sql:
select decode(reg.trade_status,'D','撤销','有效') as effectiveStatusName, decode(reg.finprod_type2,'F01','01','02') as finprodType2, reg.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, reg.ps as ps, reg.trade_market as tradeMarket, decode(reg.settle_speed,0,'01',1,'02',2,'03') as settleSpeed, reg.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdName, nvl(reg.face_value,0)/10000 as faceValue, case when reg.finprod_type2='F01' and reg.ps in ('T01','T02') then reg.yield when reg.finprod_id in ('F02','F03') then reg.rate else null end as tradeYield, reg.repo_term as termDays, reg.trade_amt as tradeAmt, reg.totle_trade_id as busiCode, reg.ou_trader_id as trader, reg.trade_date as tradeDate, reg.counter_id as counterId, mcci.PARTY_ABBR as counterIdName, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, reg.quote_type as quoteType, reg.remark as remark, reg.totle_trade_id as totleTradeId, decode(reg.trade_status,'D','03','02') effectiveStatus, case when match.trd_conf_status is null and reg.trade_status in ('01', '02') then '01' when match.trd_conf_status='1' and reg.trade_status in ('01', '02') then '02' when reg.trade_status ='D' then '03' end as regStatus, '04' as dealType, reg.settle_date as settleDate, reg.delivery_type as deliveryType, reg.v_settle_date as vsettleDate, reg.m_settle_date as msettleDate, null as pledgeFinprodIds, null as pledgeRatios, null as pledgeFaceValues from reg_fin_product_deal_total reg left join fin_product fp on fp.finprod_id=reg.finprod_id inner join ( select regdeal.totle_trade_id,wm_concat(regdeal.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName from reg_fin_product_deal regdeal left join ptl_portfolio pp on regdeal.portfolio_id=pp.portfolio_id where 1=1
AND regdeal.portfolio_id in
#{item}
group by regdeal.totle_trade_id )deal on reg.totle_trade_id=deal.totle_trade_id left join trdquto_match_info match on reg.totle_trade_id=match.pre_trade_id left join stl_sec_acct_info stlinfo on reg.sec_manage_acct_id=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON reg.counter_id= mcci.party_id where reg.trade_date= #{sysDate}
and match.trd_conf_status is null and reg.trade_status in ('01', '02')
and (reg.create_user= #{userId} or reg.update_user= #{userId})
AND reg.ps=#{ps}
AND reg.finprod_type2 in
#{item}
AND reg.finprod_id in
#{item}
AND reg.trade_market=#{tradeMarket,jdbcType=VARCHAR}
AND reg.settle_speed = #{settleSpeed,jdbcType=VARCHAR}
AND reg.sec_manage_acct_id in
#{item}
AND reg.totle_trade_id like '%' || #{busiCode,jdbcType=VARCHAR} || '%'
AND reg.quote_type= #{quoteType,jdbcType=VARCHAR}
AND '04'= #{dealType,jdbcType=VARCHAR}
AND reg.counter_id= #{counterId,jdbcType=VARCHAR}

select '流程中' as effectiveStatusName, decode(reg.finprod_type2,'F01','01','02') as finprodType2, reg.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, reg.ps as ps, reg.trade_market as tradeMarket, decode(reg.settle_speed,0,'01',1,'02',2,'03') as settleSpeed, reg.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdName, nvl(reg.face_value,0)/10000 as faceValue, case when reg.finprod_type2='F01' and reg.ps in ('T01','T02') then reg.yield when reg.finprod_id in ('F02','F03') then reg.rate else null end as tradeYield, reg.repo_term as termDays, reg.trade_amt as tradeAmt, reg.totle_trade_id as busiCode, reg.ou_trader_id as trader, reg.trade_date as tradeDate, reg.counter_id as counterId, mcci.PARTY_ABBR as counterIdName, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, reg.quote_type as quoteType, reg.remark as remark, reg.totle_trade_id as totleTradeId, '01' effectiveStatus, null regStatus, '04' as dealType, reg.settle_date as settleDate, reg.delivery_type as deliveryType, reg.v_settle_date as vsettleDate, reg.m_settle_date as msettleDate, null as pledgeFinprodIds, null as pledgeRatios, null as pledgeFaceValues from wfl_reg_fin_product_deal_total reg left join fin_product fp on fp.finprod_id=reg.finprod_id inner join ( select regdeal.totle_trade_id,wm_concat(regdeal.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName from wfl_reg_fin_product_deal regdeal left join ptl_portfolio pp on regdeal.portfolio_id=pp.portfolio_id where 1=1
AND regdeal.portfolio_id in
#{item}
group by regdeal.totle_trade_id )deal on reg.totle_trade_id=deal.totle_trade_id left join trdquto_match_info match on reg.totle_trade_id=match.pre_trade_id left join stl_sec_acct_info stlinfo on reg.sec_manage_acct_id=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON reg.counter_id= mcci.party_id where reg.trade_date= #{sysDate}
and match.trd_conf_status is null and reg.trade_status in ('01', '02')
and (reg.create_user= #{userId} or reg.update_user= #{userId})
AND reg.ps=#{ps}
AND reg.finprod_type2 in
#{item}
AND reg.finprod_id in
#{item}
AND reg.trade_market=#{tradeMarket,jdbcType=VARCHAR}
AND reg.settle_speed = #{settleSpeed,jdbcType=VARCHAR}
AND reg.sec_manage_acct_id in
#{item}
AND reg.totle_trade_id like '%' || #{busiCode,jdbcType=VARCHAR} || '%'
AND reg.quote_type= #{quoteType,jdbcType=VARCHAR}
AND '04'= #{dealType,jdbcType=VARCHAR}
AND reg.counter_id= #{counterId,jdbcType=VARCHAR}

if.where:
((aaa.effectiveStatusName || '|' || sdl.ITEM_VALUE || '|' || aaa.finprodMarketId || '|' || aaa.finprodAbbr
|| '|' || dictps.ITEM_VALUE || '|' || dicttradeMarket.ITEM_VALUE || '|T+' || aaa.settleSpeed
|| '|' || aaa.secManageAcctIdName || '|' || aaa.busiCode || '|' || aaa.trader
|| '|' || aaa.counterId  || '|' || aaa.counterIdName || '|' || aaa.portfolioIds  || '|' || aaa.portfolioNames
|| '|' || aaa.quoteType || '|' || aaa.remark
like '%' || #{search} || '%')
or to_char(aaa.faceValue,'FM9999999999999990.99')=#{search} or to_char(aaa.faceValue)=#{search}
or to_char(aaa.tradeYield,'FM99990.9990')=#{search} or  aaa.tradeYield||'' =#{search}
or aaa.termDays||'' =#{search}
or to_char(aaa.tradeAmt,'FM9999999999999990.99')=#{search} or to_char(aaa.tradeAmt)=#{search}
or aaa.tradeDate||'' =#{search}
or aaa.tradeDate||'' =#{year}||'-'||#{search}
or replace(aaa.tradeDate,'-','/')||'' =#{search}
or replace(aaa.tradeDate,'-','/')||'' =#{year}||'/'||#{search}
)

mapper.sql:
select '有效' as effectiveStatusName, '01' as finprodType2, ib.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, ib.ps as ps, '01' as tradeMarket, decode(ib.settle_speed,0,'01',1,'02',2,'03') as settleSpeed, ib.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdName, nvl(ib.share_amt,0)/100 as faceValue, ibd.yield as tradeYield, null as termDays, ib.fprice_amt as tradeAmt, ib.quote_id as busiCode, ib.ou_trader_id as trader, ib.quote_date as tradeDate, ibd.cp_party_id as counterId, mcci.PARTY_ABBR as counterIdName, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, null as quoteType, ib.remark as remark, ib.quote_id as totleTradeId, '02' effectiveStatus, case when match.trd_conf_status is null then '01' when match.trd_conf_status='1' then '02' end as regStatus, ib.quote_type as dealType, ib.settle_date as settleDate, ib.delivery_type as deliveryType, null as vsettleDate, null as msettleDate, null as pledgeFinprodIds, null as pledgeRatios, null as pledgeFaceValues from ibu_quote_bond ib left join ( select I.* from ibu_quote_bond_det I INNER JOIN (SELECT quote_id ,MAX(update_time) UPDATETIME FROM ibu_quote_bond_det GROUP BY quote_id) II ON I.quote_id = II.quote_id AND II.UPDATETIME = I.Update_Time )ibd on ib.quote_id=ibd.quote_id left join fin_product fp on ib.finprod_id=fp.finprod_id left join( select ir.quote_id,wm_concat(ir.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName from ibu_quote_etr_re ir left join ptl_portfolio pp on ir.portfolio_id=pp.portfolio_id
AND pp.portfolio_id in
#{item}
group by ir.quote_id)deal on ib.quote_id=deal.quote_id left join trdquto_match_info match on ib.quote_id=match.pre_trade_id left join stl_sec_acct_info stlinfo on ib.sec_manage_acct_id=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON ibd.cp_party_id= mcci.party_id
where ib.quote_date= #{sysDate}
and match.trd_conf_status is null
and (ib.create_user= #{userId} or ib.update_user= #{userId})
AND ib.ps=#{ps}
AND '01'=#{regAssetType}
AND '01'=#{tradeMarket,jdbcType=VARCHAR}
AND ib.settle_speed = #{settleSpeed,jdbcType=VARCHAR}
AND ib.sec_manage_acct_id in
#{item}
AND ib.quote_id like '%' || #{busiCode,jdbcType=VARCHAR} || '%'
AND ib.quote_type= #{dealType,jdbcType=VARCHAR}
AND null= #{quoteType,jdbcType=VARCHAR}
AND ibd.cp_party_id= #{counterId,jdbcType=VARCHAR}
union all select '有效' as effectiveStatusName, '02' as finprodType2, ic.term_type as finprodId, ic.term_type as finprodMarketId, null as finprodAbbr, ic.repo_ps as ps, '01' as tradeMarket, decode(ic.settle_speed,0,'01',1,'02',2,'03') as settleSpeed, ic.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdName, null as faceValue, ic.rate as tradeYield, ic.term as termDays, ic.fprice_amt as tradeAmt, ic.quote_id as busiCode, ic.ou_trader_id as trader, ic.quote_date as tradeDate, ic.cp_party_id as counterId, mcci.PARTY_ABBR as counterIdName, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, null as quoteType, ic.remark as remark, ic.quote_id as totleTradeId, '02' effectiveStatus, case when match.trd_conf_status is null then '01' when match.trd_conf_status='1' then '02' end as regStatus, ic.quote_type as dealType, ic.quote_date as settleDate, null as deliveryType, ic.v_settle_date as vsettleDate, ic.m_settle_date as msettleDate, icpledge.pledgeFinprodId as pledgeFinprodIds, icpledge.pledgeRatio as pledgeRatios, icpledge.pledgeFaceValue as pledgeFaceValues from ibu_quote_crep ic left join ( select I.quote_id, wm_concat(i.pledge_finprod_id) as pledgeFinprodId,wm_concat(i.pledge_ratio) pledgeRatio, wm_concat(i.pledge_face_value) pledgeFaceValue from (select * from ibu_quote_crep_pledge order by pledge_finprod_id) I group by I.quote_id )icpledge on ic.quote_id=icpledge.quote_id left join( select ir.quote_id,wm_concat(ir.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName from ibu_quote_etr_re ir left join ptl_portfolio pp on ir.portfolio_id=pp.portfolio_id
AND pp.portfolio_id in
#{item}
group by ir.quote_id)deal on ic.quote_id=deal.quote_id left join trdquto_match_info match on ic.quote_id=match.pre_trade_id left join stl_sec_acct_info stlinfo on ic.sec_manage_acct_id=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON ic.cp_party_id= mcci.party_id where ic.quote_date= #{sysDate}
and match.trd_conf_status is null
and (ic.create_user= #{userId} or ic.update_user= #{userId})
AND ic.repo_ps=#{ps}
AND '02'=#{regAssetType}
AND '01'=#{tradeMarket,jdbcType=VARCHAR}
AND ic.settle_speed = #{settleSpeed,jdbcType=VARCHAR}
AND ic.sec_manage_acct_id in
#{item}
AND ic.quote_id like '%' || #{busiCode,jdbcType=VARCHAR} || '%'
AND ic.quote_type= #{dealType,jdbcType=VARCHAR}
AND null= #{quoteType,jdbcType=VARCHAR}
AND ic.cp_party_id= #{counterId,jdbcType=VARCHAR}

mapper.select:
select 'F01' as finprodType2, ib.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, ib.ps as ps, '01' as tradeMarket, ib.settle_speed as settleSpeed, ib.sec_manage_acct_id as secManageAcctId, nvl(ib.share_amt,0)*100 as faceValue, ibd.yield tradeYield, null as termDays, ib.fprice_amt as tradeAmt, ib.ou_trader_id as trader, ib.quote_date as tradeDate, ibd.cp_party_id as counterId, ib.quote_type as quoteType, ib.remark as remark, ib.quote_id as totleTradeId, ib.OU_PARTY_ID as ouPartyId, ib.OU_TRADER_ID as ouTraderId, ibd.CP_PARTY_ID as cpPartyId, ibd.CP_TRADER as cpTrader, i.OURDEPOSITACCOUNTNUMBER as secManageAcctId, ib.settle_date as settleDate, fp.ccy as ccy, ibd.unit_cprice unitCprice, ibd.unit_fprice as unitFprice, ibd.unit_int as unitInt, ibd.yield as yield, ibd.share_amt as shareAmt, ibd.par_value as parValue, ibd.fprice_amt fpriceAmt, ibd.cprice_amt as cpriceAmt, ibd.int_amt as intAmt, ibd.exer_yield as exerYield
from ibu_quote_bond ib left join ( select I.* from ibu_quote_bond_det I INNER JOIN (SELECT quote_id ,MAX(update_time) UPDATETIME FROM ibu_quote_bond_det GROUP BY quote_id) II ON I.quote_id = II.quote_id AND II.UPDATETIME = I.Update_Time )ibd on ib.quote_id=ibd.quote_id left join fin_product fp on ib.finprod_id=fp.finprod_id left join trdquto_match_info match on ib.quote_id=match.pre_trade_id left join ( select i.* from interf_cstp_trade I INNER JOIN (SELECT EXECID ,MAX(UPDATETIME) UPDATETIME FROM INTERF_CSTP_TRADE GROUP BY EXECID) II ON II.EXECID = I.EXECID AND II.UPDATETIME = I.UPDATETIME )i on match.exe_id=i.execid
where ib.quote_id= #{totleTradeId,jdbcType=VARCHAR}

mapper.update:
update trdquto_match_info
set TRD_CONF_STATUS= #{trdConfStatus,jdbcType=VARCHAR},
UPDATE_USER= #{updateUser,jdbcType=VARCHAR},
UPDATE_TIME = sysdate,
TRD_ID=#{trdId,jdbcType=VARCHAR}
where PRE_TRADE_ID=#{preTradeId,jdbcType=VARCHAR}

mapper.select:
select * from (select aaa.* from (select I.Execid as execid, I.Businesstype as businesstype, decode(I.BUSINESSTYPE,'BOND',ts.SECID,'REPO',tr.secid) as finprodMarketId, decode(I.BUSINESSTYPE,'BOND',fp.finprod_abbr,'REPO',null) as finprodAbbr, nvl(ts.ps,tr.ps) as ps, decode(decode(I.BUSINESSTYPE,'BOND',ts.SETTLE_SPEED,'REPO',tr.SETTLE_SPEED),'1','01','2','02','3','03') settleSpeed,
case when ipar.portfolio_id is not null then i.OURDEPOSITACCOUNTNUMBER else i.COUNTERDEPOSITACCOUNTNUMBER end as acctNo, stlinfo.sec_acct_name as acctNoName, nvl(I.LASTQTY,0)/10000 as lastqty, decode(I.BUSINESSTYPE, 'BOND', I.yield2, 'REPO', I.PRICE) tradeYield, decode(I.BUSINESSTYPE, 'BOND', '', 'REPO', I.TRADELIMITDAYS) termDays, I.TRADECASHAMT as tradeAmt, QUOTE.QUOTEID as quoteid, I.ourinstitutioncode as traderid, mccit.PARTY_ABBR as traderidName, su.USER_NAME trader, I.Counterinstitutioncode as counterId, mccic.PARTY_ABBR as counterIdName, I.Clearingmethod as clearType, nvl(ts.dealdate,tr.dealdate) as tradeDate, nvl(ts.dealtext,tr.dealtext) as remark, nvl(ts.dealno,tr.tradeid) as cstpTradeId, I.deliveryType as deliveryType, to_date(I.Settldate,'yyyy-MM-dd') as vsettleDate, to_date(I.Settldate2,'yyyy-MM-dd') as msettleDate, nvl(ts.settdate,tr.dealdate) as settleDate from INTERF_CSTP_TRADE I INNER JOIN (SELECT EXECID ,MAX(UPDATETIME) UPDATETIME FROM INTERF_CSTP_TRADE GROUP BY EXECID) II ON II.EXECID = I.EXECID AND II.UPDATETIME = I.UPDATETIME left join INTERF_OPICS_TRAD_REPO tr on tr.oritradeid = I.EXECID left join INTERF_TRAD_SECDEAL ts on ts.FEDEALNO = I.EXECID left join fin_product fp on ts.SECID=fp.finprod_market_id and fp.finprod_type='F01' LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON I.OURINSTITUTIONCODE= mcci.PARTY_CUSTOMER_ID LEFT JOIN IBU_PORTFOLIO_ACCT_RELA ipar ON mcci.PARTY_ID =ipar.PARTY_ID LEFT JOIN SYS_USER_ADD sua ON nvl(ts.TRAD,tr.BUYTRADER) =sua.IBU_TRADER LEFT JOIN SYS_USER su ON sua.USER_ID =su.USER_ID LEFT JOIN ( SELECT distinct i.EXECID ,nvl(iqb.QUOTE_ID,iqc.QUOTE_ID) QUOTEID FROM INTERF_CSTP_TRADE i LEFT JOIN IBU_QUOTE_BOND_DET iqbd ON i.EXECID = iqbd.EXECID LEFT JOIN IBU_QUOTE_BOND iqb ON iqbd.QUOTE_ID = iqb.QUOTE_ID LEFT JOIN IBU_QUOTE_ETR_RE iqerb ON iqb.QUOTE_ID = iqerb.QUOTE_ID LEFT JOIN IBU_QUOTE_CREP iqc ON i.EXECID = iqc.EXECID LEFT JOIN IBU_QUOTE_ETR_RE iqerr ON iqc.QUOTE_ID = iqerr.QUOTE_ID ) QUOTE ON QUOTE.EXECID=I.EXECID left join stl_sec_acct_info stlinfo on (case when ipar.portfolio_id is not null then i.OURDEPOSITACCOUNTNUMBER else i.COUNTERDEPOSITACCOUNTNUMBER end)=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mccit ON I.ourinstitutioncode= mccit.party_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON I.Counterinstitutioncode= mccic.party_id where I.BUSINESSTYPE in ('BOND','REPO')
AND I.BUSINESSTYPE = #{regAssetType}
AND (nvl(ts.SECID,tr.SECID) in
#{item}
or ts.SECID in
CONCAT(#{item},'.IB')
or fp.finprod_id in
#{item}
)
and I.Execid LIKE CONCAT('%',CONCAT(#{execid},'%'))
and QUOTE.QUOTEID LIKE CONCAT('%',CONCAT(#{quoteid},'%'))
AND I.ourinstitutioncode IN
#{item}
AND I.Counterinstitutioncode IN
#{item}
and decode(decode(I.BUSINESSTYPE,'BOND',ts.SETTLE_SPEED,'REPO',tr.SETTLE_SPEED),'1','01','2','02','3','03') = #{settleSpeed}
AND nvl(ts.OURDEPOSITACCOUNTNUMBER,ts.OURDEPOSITACCOUNTNUMBER) IN
#{item}
and su.USER_NAME= #{userId}
)aaa left join SYS_DATADICT_LIST sdl on aaa.businesstype=sdl.ITEM_CODE and sdl.DICT_CODE='CSTP_BUSINESS_TYPE' left join SYS_DATADICT_LIST dictps on aaa.PS=dictps.ITEM_CODE and dictps.DICT_CODE='PS' left join SYS_DATADICT_LIST dictct on aaa.clearType=dictct.ITEM_CODE and dictct.DICT_CODE='CLEAR_TYPE' left join SYS_DATADICT_LIST dictss on aaa.settleSpeed=dictss.ITEM_CODE and dictss.DICT_CODE='ACCOUNT_SPEED'
order by aaa.businesstype,aaa.ps,aaa.finprodMarketId)
order by ${sort} ${direction}

if.where:
((aaa.execid || '|' || sdl.ITEM_VALUE || '|' || aaa.finprodMarketId || '|' || aaa.finprodAbbr
|| '|' || dictps.ITEM_VALUE || '|' || dictss.ITEM_VALUE
|| '|' || aaa.acctNoName || '|' || aaa.quoteid  || '|' || aaa.traderidName || '|' || aaa.trader
|| '|' || aaa.counterIdName || '|' || dictct.ITEM_VALUE || '|' || aaa.remark
like '%' || #{search} || '%')
or to_char(aaa.lastqty,'FM9999999999999990.90')=#{search} or to_char(aaa.lastqty)=#{search}
or to_char(aaa.tradeYield,'FM99990.9990')=#{search} or  aaa.tradeYield||'' =#{search}
or aaa.termDays||'' =#{search}
or to_char(aaa.tradeAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.tradeAmt)=#{search}
or aaa.tradeDate||'' =#{search}
or aaa.tradeDate||''=#{year}||'-'||#{search}
or replace(aaa.tradeDate,'-','/')||''=#{search}
or replace(aaa.tradeDate,'-','/')||''=#{year}||'/'||#{search}
)

mapper.select:
select * from (select aaa.* from ( select distinct m.seqno as seqno, m.match_type as matchType, m.pre_trade_id as busiCode, m.exe_id as execid, ct.BUSINESSTYPE as finprodType2, decode(ct.BUSINESSTYPE,'BOND','债券','REPO','质押式回购') as finprodType2Name, decode(ct.BUSINESSTYPE,'BOND',fp.finprod_market_id,'REPO',reg.term_type) as finprodMarketId, decode(ct.BUSINESSTYPE,'BOND',fp.finprod_abbr,null) as finprodAbbr, reg.ps as ps, reg.settle_speed as settleSpeed,
case when ipar.portfolio_id is not null then ct.OURDEPOSITACCOUNTNUMBER else ct.COUNTERDEPOSITACCOUNTNUMBER end as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdName, decode(ct.BUSINESSTYPE,'BOND',nvl(reg.face_value,0)/10000,null) as printAmt, decode(ct.BUSINESSTYPE,'BOND',reg.yield,reg.rate) as tradeYield, decode(ct.BUSINESSTYPE,'REPO',reg.repo_term,null) as termDays, decode(ct.BUSINESSTYPE,'BOND',reg.fprice_amt,tr.vdealamt) as tradeAmt, reg.trade_date as tradeDate, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, regfee.trdFeeAmt as trdFeeAmt, regfee.settleFeeAmt as settleFeeAmt, reg.counter_id as counterId, mccic.PARTY_ABBR as counterIdName, reg.quote_type as quoteType, m.trd_conf_status as trdConfStatus, m.match_status as matchStatus, '04' as dealType, m.pre_trade_id as totleTradeId from trdquto_match_info m left join reg_fin_product_deal_total reg on m.pre_trade_id=reg.totle_trade_id left join fin_product fp on reg.finprod_id=fp.finprod_id inner join( select regdeal.totle_trade_id,wm_concat(regdeal.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName from reg_fin_product_deal regdeal left join ptl_portfolio pp on regdeal.portfolio_id=pp.portfolio_id where 1=1
AND regdeal.portfolio_id in
#{item}
group by regdeal.totle_trade_id)deal on reg.totle_trade_id=deal.totle_trade_id left join ( select fee.trade_id,sum(decode(fee.fee_type,'B06',fee.fee_amt)) as trdFeeAmt, sum(decode(fee.fee_type,'B08',fee.fee_amt)) as settleFeeAmt from reg_trade_fee_total fee group by fee.trade_id ) regfee on reg.totle_trade_id=regfee.trade_id left join (SELECT I.* FROM INTERF_CSTP_TRADE I INNER JOIN (SELECT EXECID, MAX(UPDATETIME) UPDATETIME FROM INTERF_CSTP_TRADE GROUP BY EXECID) II ON II.EXECID = I.EXECID AND II.UPDATETIME = I.UPDATETIME) ct on ct.EXECID = m.exe_id left join INTERF_OPICS_TRAD_REPO tr on tr.oritradeid =m.exe_id and tr.Tradeid=m.cstp_trade_id left join INTERF_TRAD_SECDEAL ts on ts.FEDEALNO = m.exe_id and ts.Dealno=m.cstp_trade_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON ct.OURINSTITUTIONCODE= mcci.PARTY_CUSTOMER_ID LEFT JOIN IBU_PORTFOLIO_ACCT_RELA ipar ON mcci.PARTY_ID =ipar.PARTY_ID left join stl_sec_acct_info stlinfo on (case when ipar.portfolio_id is not null then ct.OURDEPOSITACCOUNTNUMBER else ct.COUNTERDEPOSITACCOUNTNUMBER end)=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON reg.counter_id= mccic.party_id
where 1=1
AND reg.ps = #{ps}
AND ct.BUSINESSTYPE = #{regAssetType}
AND (nvl(ts.SECID,tr.SECID) in
#{item}
or ts.SECID in
CONCAT(#{item},'.IB')
)
AND reg.quote_type = #{quoteType}
and reg.settle_speed = #{settleSpeed}
AND nvl(ts.OURDEPOSITACCOUNTNUMBER,ts.OURDEPOSITACCOUNTNUMBER) IN
#{item}
and m.exe_id LIKE CONCAT('%',CONCAT(#{exeid},'%'))
and m.pre_trade_id LIKE CONCAT('%',CONCAT(#{busiCode},'%'))
and m.match_type= #{matchType}
and reg.counter_id= #{counterId}
AND m.trd_conf_status IN
#{item}
union all select m.seqno as seqno, m.match_type as matchType, m.pre_trade_id as busiCode, m.exe_id as execid, ct.BUSINESSTYPE as finprodType2, decode(ct.BUSINESSTYPE,'BOND','债券','REPO','质押式回购') as finprodType2Name, decode(ct.BUSINESSTYPE,'BOND',fp.finprod_market_id,'REPO',ic.term_type) as finprodMarketId, decode(ct.BUSINESSTYPE,'BOND',fp.finprod_abbr,null) as finprodAbbr, nvl(ib.ps,ic.repo_ps) as ps, nvl(ib.settle_speed,ic.settle_speed) as settleSpeed,
case when ipar.portfolio_id is not null then ct.OURDEPOSITACCOUNTNUMBER else ct.COUNTERDEPOSITACCOUNTNUMBER end as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdName, decode(ct.BUSINESSTYPE,'BOND',nvl(ib.share_amt,0)/100,null) as printAmt, decode(ct.BUSINESSTYPE,'BOND',ib.yield,ic.rate) as tradeYield, decode(ct.BUSINESSTYPE,'REPO',ic.term,null) as termDays, decode(ct.BUSINESSTYPE,'BOND',ib.fprice_amt,tr.vdealamt) as tradeAmt, nvl(ib.quote_date,ic.quote_date) as tradeDate, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, null as trdFeeAmt, null as settleFeeAmt, nvl(ib.cp_party_id,ic.cp_party_id) as counterId, mccic.PARTY_ABBR as counterIdName, nvl(ib.quote_type,ic.quote_type) as quoteType, m.trd_conf_status as trdConfStatus, m.match_status as matchStatus, nvl(ib.quote_type,ic.quote_type) as dealType, m.pre_trade_id as totleTradeId from trdquto_match_info m left join ( select row_number() over (PARTITION BY t2.quote_id order by t2.update_time desc) as rn, t1.quote_id,t1.ps,t1.settle_speed,t1.share_amt,t1.finprod_id,t1.quote_type, t2.yield,t1.fprice_amt,t1.quote_date,t2.cp_party_id from ibu_quote_bond t1 left join ibu_quote_bond_det t2 on t1.quote_id=t2.quote_id ) ib on m.pre_trade_id=ib.quote_id and ib.rn=1 left join ibu_quote_crep ic on m.pre_trade_id=ic.quote_id left join fin_product fp on ib.finprod_id=fp.finprod_id inner join( select ir.quote_id,wm_concat(ir.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName from ibu_quote_etr_re ir left join ptl_portfolio pp on ir.portfolio_id=pp.portfolio_id where 1=1
AND ir.portfolio_id in
#{item}
group by ir.quote_id)deal on m.pre_trade_id=deal.quote_id left join (SELECT I.* FROM INTERF_CSTP_TRADE I INNER JOIN (SELECT EXECID, MAX(UPDATETIME) UPDATETIME FROM INTERF_CSTP_TRADE GROUP BY EXECID) II ON II.EXECID = I.EXECID AND II.UPDATETIME = I.UPDATETIME) ct on ct.EXECID = m.exe_id left join INTERF_OPICS_TRAD_REPO tr on tr.oritradeid =m.exe_id and tr.Tradeid=m.cstp_trade_id left join INTERF_TRAD_SECDEAL ts on ts.FEDEALNO = m.exe_id and ts.Dealno=m.cstp_trade_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON ct.OURINSTITUTIONCODE= mcci.PARTY_CUSTOMER_ID LEFT JOIN IBU_PORTFOLIO_ACCT_RELA ipar ON mcci.PARTY_ID =ipar.PARTY_ID left join stl_sec_acct_info stlinfo on (case when ipar.portfolio_id is not null then ct.OURDEPOSITACCOUNTNUMBER else ct.COUNTERDEPOSITACCOUNTNUMBER end)=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON nvl(ib.cp_party_id,ic.cp_party_id)= mcci.party_id where ct.BUSINESSTYPE in ('BOND','REPO') and (ic.quote_id is not null or ib.quote_id is not null)
AND nvl(ib.ps,ic.repo_ps) = #{ps}
AND ct.BUSINESSTYPE = #{regAssetType}
AND (nvl(ts.SECID,tr.SECID) in
#{item}
or ts.SECID in
CONCAT(#{item},'.IB')
)
AND nvl(ib.quote_type,ic.quote_type) = #{quoteType}
and nvl(ib.settle_speed,ic.settle_speed) = #{settleSpeed}
AND nvl(ts.OURDEPOSITACCOUNTNUMBER,ts.OURDEPOSITACCOUNTNUMBER) IN
#{item}
and m.exe_id LIKE CONCAT('%',CONCAT(#{exeid},'%'))
and m.pre_trade_id LIKE CONCAT('%',CONCAT(#{busiCode},'%'))
and m.match_type= #{matchType}
and nvl(ib.cp_party_id,ic.cp_party_id)= #{counterId}
AND m.trd_conf_status IN
#{item}
)aaa left join SYS_DATADICT_LIST sdl on aaa.matchType=sdl.ITEM_CODE and sdl.DICT_CODE='TRD_MATCH_TYPE' left join SYS_DATADICT_LIST dictps on aaa.PS=dictps.ITEM_CODE and dictps.DICT_CODE='PS' left join SYS_DATADICT_LIST dictquoteTpe on aaa.dealType=dictquoteTpe.ITEM_CODE and dictquoteTpe.DICT_CODE='QUOTE_TYPE'
order by aaa.matchType,aaa.quoteType,aaa.finprodType2,aaa.ps,aaa.finprodMarketId)
order by ${sort} ${direction}

if.where:
((aaa.execid || '|' || aaa.busiCode || '|' || sdl.ITEM_VALUE || '|' || aaa.finprodMarketId
|| '|' || aaa.finprodAbbr || '|' || dictps.ITEM_VALUE
|| '|' || aaa.finprodType2Name || '|T+' || aaa.settleSpeed
|| '|' || aaa.secManageAcctIdName || '|' || aaa.portfolioIds  || '|' || aaa.portfolioNames
|| '|' || aaa.counterIdName || '|' || dictquoteTpe.ITEM_VALUE
like '%' || #{search} || '%')
or to_char(aaa.printAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.printAmt)=#{search}
or to_char(aaa.tradeYield,'FM99990.9990')=#{search} or  aaa.tradeYield||'' =#{search}
or aaa.termDays||'' =#{search}
or to_char(aaa.tradeAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.tradeAmt)=#{search}
or to_char(aaa.trdFeeAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.trdFeeAmt)=#{search}
or to_char(aaa.settleFeeAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.settleFeeAmt)=#{search}
or aaa.tradeDate||'' =#{search}
or aaa.tradeDate||''=#{year}||'-'||#{search}
or replace(aaa.tradeDate,'-','/')||''=#{search}
or replace(aaa.tradeDate,'-','/')||''=#{year}||'/'||#{search}
)

mapper.select:
select * from ( select ts.fedealno as execid, ts.dealdate as tradeDate, fp.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, ts.ps as ps, ts.settle_speed as settleSpeed,
case when ipar.portfolio_id is not null then i.OURDEPOSITACCOUNTNUMBER else i.COUNTERDEPOSITACCOUNTNUMBER end as acctNo, stlinfo.sec_acct_name as acctNoName, ts.settdate as settleDate, ts.price_8 as unitCprice, I.yield2 as yield, I.Strikeyield as exerYield, ts.prinamt as lastqty, ts.unit_int as unitInt, ts.dirtyprice as unitFprice, I.tradecashamt as tradeAmt, I.accruedinteresttotalamt as intAmt, ts.settamt as mtradeAmt, I.Clearingmethod as clearType, I.Deliverytype as deliveryType, I.Settlcurrency as settCcy, I.Quoteid as quoteid, I.ourinstitutioncode as traderid, mccit.PARTY_ABBR as traderidName, su.USER_NAME trader, I.Counterinstitutioncode as counterId, mccic.PARTY_ABBR as counterIdName, I.Institutionenglishshortname as counterTrader, ts.dealtext from INTERF_CSTP_TRADE I INNER JOIN (SELECT EXECID ,MAX(UPDATETIME) UPDATETIME FROM INTERF_CSTP_TRADE GROUP BY EXECID) II ON II.EXECID = I.EXECID AND II.UPDATETIME = I.UPDATETIME left join INTERF_TRAD_SECDEAL ts on ts.FEDEALNO = I.EXECID left join fin_product fp on ts.secid=fp.finprod_market_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON I.OURINSTITUTIONCODE= mcci.PARTY_CUSTOMER_ID LEFT JOIN IBU_PORTFOLIO_ACCT_RELA ipar ON mcci.PARTY_ID =ipar.PARTY_ID LEFT JOIN SYS_USER_ADD sua ON ts.TRAD =sua.IBU_TRADER LEFT JOIN SYS_USER su ON sua.USER_ID =su.USER_ID left join stl_sec_acct_info stlinfo on (case when ipar.portfolio_id is not null then i.OURDEPOSITACCOUNTNUMBER else i.COUNTERDEPOSITACCOUNTNUMBER end)=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mccit ON I.ourinstitutioncode= mccit.party_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON I.Counterinstitutioncode= mccic.party_id where I.EXECID=#{exeid,jdbcType=VARCHAR} )
order by ${sort} ${direction}

select * from ( select tr.oritradeid as execid, tr.dealdate as tradeDate, tr.term_type as termType, tr.ps as ps,
case when ipar.portfolio_id is not null then i.OURDEPOSITACCOUNTNUMBER else i.COUNTERDEPOSITACCOUNTNUMBER end as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdName, tr.settle_speed as settleSpeed, tr.term as repoTerm, I.Settldate as vsettleDate, I.Settldate2 as msettleDate, I.Cashholdingdays as actRepoTerm, I.Price as tradeYield, I.Tradecashamt as tradeAmt, I.Accruedinteresttotalamt as mintAmt, I.Settlcurramt2 as mtradeAmt, tr.deal_feeamt as trdFeeAmt, tr.sett_feeamt as settleFeeAmt, I.Clearingmethod as clearType, I.Deliverytype as deliveryType, I.Deliverytype2 as mdeliveryType, I.Settlcurrency as settCcy, I.Quoteid as quoteid, I.ourinstitutioncode as traderid, mccit.PARTY_ABBR as traderidName, su.USER_NAME trader, I.Counterinstitutioncode as counterId, mccic.PARTY_ABBR as traderidName, I.Institutionenglishshortname as counterTrader, tr.dealtext as remark from INTERF_CSTP_TRADE I INNER JOIN (SELECT EXECID ,MAX(UPDATETIME) UPDATETIME FROM INTERF_CSTP_TRADE GROUP BY EXECID) II ON II.EXECID = I.EXECID AND II.UPDATETIME = I.UPDATETIME left join INTERF_OPICS_TRAD_REPO tr on tr.oritradeid = I.EXECID LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON I.OURINSTITUTIONCODE= mcci.PARTY_CUSTOMER_ID LEFT JOIN IBU_PORTFOLIO_ACCT_RELA ipar ON mcci.PARTY_ID =ipar.PARTY_ID LEFT JOIN SYS_USER_ADD sua ON tr.BUYTRADER =sua.IBU_TRADER LEFT JOIN SYS_USER su ON sua.USER_ID =su.USER_ID on (case when ipar.portfolio_id is not null then i.OURDEPOSITACCOUNTNUMBER else i.COUNTERDEPOSITACCOUNTNUMBER end)=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mccit ON I.ourinstitutioncode= mccit.party_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON I.Counterinstitutioncode= mccic.party_id where I.EXECID=#{exeid,jdbcType=VARCHAR} )
order by ${sort} ${direction}
